//
//	  val = rtw_read16(rtwdev, addr);
//	  rtw_write16(rtwdev, addr, val & ~bit);
//}
//
//static inline void rtw_write32_clr(struct rtw_dev *rtwdev, u32 addr, u32 bit)
//{
//	  u32 val;
//
//	  val = rtw_read32(rtwdev, addr);
//	  rtw_write32(rtwdev, addr, val & ~bit);
//}

bool check_hw_ready(struct rtw_dev *rtwdev, u32 addr, u32 mask, u32 target)
{
	u32 cnt;

	for (cnt = 0; cnt < 1000; cnt++) {
		if (rtw_read32_mask(rtwdev, addr, mask) == target)
			return true;

		// XXX:misha udelay?
//		  udelay(10);
		DELAY(10);
	}

//	printf("%s: target=%d\n", __func__, target);
//	printf("%s: rtw_read32_mask(rtwdev, addr, mask)=%d\n", __func__, rtw_read32_mask(rtwdev, addr, mask));
	return false;
}


