static void rtw8822b_cfg_ldo25(struct rtw_dev *rtwdev, bool enable)
{
        u8 ldo_pwr;

        ldo_pwr = rtw_read8(rtwdev, REG_LDO_EFUSE_CTRL + 3);
        ldo_pwr = enable ? ldo_pwr | BIT_LDO25_EN : ldo_pwr & ~BIT_LDO25_EN;
        rtw_write8(rtwdev, REG_LDO_EFUSE_CTRL + 3, ldo_pwr);
}

#define RTW_EFUSE_BANK_WIFI             0x0

static void switch_efuse_bank(struct rtw_dev *rtwdev)
{
        rtw_write32_mask(rtwdev, REG_LDO_EFUSE_CTRL, BIT_MASK_EFUSE_BANK_SEL,
                         RTW_EFUSE_BANK_WIFI);
}

static inline void rtw_chip_efuse_grant_on(struct rtw_dev *rtwdev)
{
	// TODO: not needed for 8822bu
//        if (rtwdev->chip->ops->efuse_grant)
//                rtwdev->chip->ops->efuse_grant(rtwdev, true);
}

static int rtw_dump_physical_efuse_map(struct rtw_dev *rtwdev, u8 *map)
{
        const struct rtw_chip_info *chip = rtwdev->chip;
        u32 size = rtwdev->efuse.physical_size;
        u32 efuse_ctl;
        u32 addr;
        u32 cnt;

        rtw_chip_efuse_grant_on(rtwdev);

        switch_efuse_bank(rtwdev);

        /* disable 2.5V LDO */
        chip->ops->cfg_ldo25(rtwdev, false);

        efuse_ctl = rtw_read32(rtwdev, REG_EFUSE_CTRL);

        for (addr = 0; addr < size; addr++) {
                efuse_ctl &= ~(BIT_MASK_EF_DATA | BITS_EF_ADDR);
                efuse_ctl |= (addr & BIT_MASK_EF_ADDR) << BIT_SHIFT_EF_ADDR;
                rtw_write32(rtwdev, REG_EFUSE_CTRL, efuse_ctl & (~BIT_EF_FLAG));

                cnt = 1000000;
                do {
//                        udelay(1);
			DELAY(1);
                        efuse_ctl = rtw_read32(rtwdev, REG_EFUSE_CTRL);
                        if (--cnt == 0)
                                return -EBUSY;
                } while (!(efuse_ctl & BIT_EF_FLAG));

                *(map + addr) = (u8)(efuse_ctl & BIT_MASK_EF_DATA);
        }

        rtw_chip_efuse_grant_off(rtwdev);

        return 0;
}

int rtw_parse_efuse_map(struct rtw_dev *rtwdev)
{
        const struct rtw_chip_info *chip = rtwdev->chip;
        struct rtw_efuse *efuse = &rtwdev->efuse;
        u32 phy_size = efuse->physical_size;
        u32 log_size = efuse->logical_size;
        u8 *phy_map = NULL;
        u8 *log_map = NULL;
        int ret = 0;

//        phy_map = kmalloc(phy_size, GFP_KERNEL);
//        log_map = kmalloc(log_size, GFP_KERNEL);
	phy_map = malloc(phy_size, M_DEVBUF, M_NOWAIT);
	log_map = malloc(log_size, M_DEVBUF, M_NOWAIT);
        if (!phy_map || !log_map) {
                ret = -ENOMEM;
                goto out_free;
        }

        ret = rtw_dump_physical_efuse_map(rtwdev, phy_map);
        if (ret) {
                printf("%s: failed to dump efuse physical map\n", __func__);
                goto out_free;
        }

        memset(log_map, 0xff, log_size);
	ret = rtw_dump_logical_efuse_map(rtwdev, phy_map, log_map);
	if (ret) {
		printf("%s: failed to dump efuse logical map\n", __func__);
		goto out_free;
	}
//
	ret = chip->ops->read_efuse(rtwdev, log_map);
	if (ret) {
		printf("%s: failed to read efuse map\n", __func__);
		goto out_free;
	}

out_free:
//        kfree(log_map);
//        kfree(phy_map);
	free(log_map, M_DEVBUF, phy_size);
	free(phy_map, M_DEVBUF, log_size);

        return ret;
}

int
rtw88_chip_efuse_enable(struct rtw_dev *rtwdev)
{
	struct urtwm_softc *sc = rtwdev->cookie;
	struct rtw_fw_state *fw = &rtwdev->fw;
	int ret;

	ret = rtw88_hci_setup(rtwdev);
	if (ret) {
		printf("%s: %s: failed to setup hci, error=%i\n",
		    sc->sc_pdev.dv_xname, __func__, ret);
		goto err;
	}

	ret = rtw88_mac_power_on(rtwdev);
	if (ret) {
		printf("%s: %s: failed to power on mac, error=%i\n",
		    sc->sc_pdev.dv_xname, __func__, ret);
		goto err;
	}

	rtw88_write8(rtwdev, REG_C2HEVT, C2H_HW_FEATURE_DUMP);

	// TODO: remove linusism
//	wait_for_completion(&fw->completion);
//	if (!fw->firmware) {
//		ret = -EINVAL;
//		rtw88_err(rtwdev, "failed to load firmware\n");
//		goto err;
//	}
	ret = loadfirmware(rtwdev->chip->fw_name, &fw->fwdata, &fw->fwsize);
	if (ret) {
		printf("%s: %s: could not read %s, error=%i\n",
		    sc->sc_pdev.dv_xname, __func__, rtwdev->chip->fw_name,
		    ret);
		goto err;
	};


	ret = rtw_download_firmware(rtwdev, fw);
	if (ret) {
		printf("%s: %s: failed to download firmware, error=%i\n",
		    sc->sc_pdev.dv_xname, __func__, ret);
		goto err_off;
	}

	return 0;
//
err_off:
	rtw_mac_power_off(rtwdev);

err:
	return ret;
}

static void rtw_chip_efuse_disable(struct rtw_dev *rtwdev)
{
        rtw_hci_stop(rtwdev);
        rtw_mac_power_off(rtwdev);
}

int
rtw88_chip_efuse_info_setup(struct rtw_dev *rtwdev) {
	struct urtwm_softc *sc = rtwdev->cookie;
	struct rtw88_efuse *efuse = &rtwdev->efuse;
	int ret;

	/* power on mac to read efuse */
	ret = rtw88_chip_efuse_enable(rtwdev);
	if (ret) {
		printf("%s: %s: rtw_chip_efuse_enable failed, error=%i\n",
		    sc->sc_pdev.dv_xname, __func__, ret);
		return ret;
	};

	ret = rtw_parse_efuse_map(rtwdev);
	if (ret)
		goto out_disable;
//
	ret = rtw_dump_hw_feature(rtwdev);
	if (ret)
		goto out_disable;
//
	ret = rtw_check_supported_rfe(rtwdev);
	if (ret)
		goto out_disable;
//
	if (efuse->crystal_cap == 0xff)
		efuse->crystal_cap = 0;
	if (efuse->pa_type_2g == 0xff)
		efuse->pa_type_2g = 0;
	if (efuse->pa_type_5g == 0xff)
		efuse->pa_type_5g = 0;
	if (efuse->lna_type_2g == 0xff)
		efuse->lna_type_2g = 0;
	if (efuse->lna_type_5g == 0xff)
		efuse->lna_type_5g = 0;
	if (efuse->channel_plan == 0xff)
		efuse->channel_plan = 0x7f;
	if (efuse->rf_board_option == 0xff)
		efuse->rf_board_option = 0;
	if (efuse->bt_setting & BIT(0))
		efuse->share_ant = true;
	if (efuse->regd == 0xff)
		efuse->regd = 0;
	if (efuse->tx_bb_swing_setting_2g == 0xff)
		efuse->tx_bb_swing_setting_2g = 0;
	if (efuse->tx_bb_swing_setting_5g == 0xff)
		efuse->tx_bb_swing_setting_5g = 0;
//
	efuse->btcoex = (efuse->rf_board_option & 0xe0) == 0x20;
	efuse->ext_pa_2g = efuse->pa_type_2g & BIT(4) ? 1 : 0;
	efuse->ext_lna_2g = efuse->lna_type_2g & BIT(3) ? 1 : 0;
	efuse->ext_pa_5g = efuse->pa_type_5g & BIT(0) ? 1 : 0;
	efuse->ext_lna_2g = efuse->lna_type_5g & BIT(3) ? 1 : 0;
//
//	if (!is_valid_ether_addr(efuse->addr)) {
//		eth_random_addr(efuse->addr);
//		dev_warn(rtwdev->dev, "efuse MAC invalid, using random\n");
//	}
//
out_disable:
	rtw_chip_efuse_disable(rtwdev);
	return ret;
}

