int
urtwm_newstate(struct ieee80211com *ic, enum ieee80211_state nstate, int arg)
{
//	struct urtwm_softc *sc = ic->ic_softc;
	enum ieee80211_state ostate;
	int /*ret,*/ s, error;

	s = splnet();
	ostate = ic->ic_state;

	if (nstate != ostate)
		printf("%s: newstate %s -> %s\n", __func__,
		    ieee80211_state_name[ostate],
		    ieee80211_state_name[nstate]);

	switch (nstate) {
	case IEEE80211_S_INIT:
		break;
	default:
		break;
	}

	error = ic->ic_newstate(ic, nstate, arg);
	splx(s);

	return (error);
}

void
urtwm_start(struct ifnet *ifp)
{
	printf("%s: \n", __func__);
}

int
urtwm_ioctl(struct ifnet *ifp, u_long cmd, caddr_t data)
{
	struct urtwm_softc *sc = ifp->if_softc;
	struct rtw88_softc *sc_sc = &sc->sc_sc;
	struct rtw_dev *rtwdev = &sc_sc->rtw_dev;
	int ret, s, error = 0;

	if (usbd_is_dying(sc->sc_udev))
		return ENXIO;

	// TODO: urtwn sets RTWN_FLAG_BUSY
	usbd_ref_incr(sc->sc_udev);
	s = splnet();
	switch (cmd) {
	case SIOCSIFADDR:
		ifp->if_flags |= IFF_UP;
		/* FALLTHROUGH */
	case SIOCSIFFLAGS:
		if (ifp->if_flags & IFF_UP) {
			if (!(ifp->if_flags & IFF_RUNNING)) {
				printf("%s: starting device\n", __func__);
				ret = rtwdev->chip->ops->power_on(rtwdev);
				if (ret)
					return ret;
			}
		} else {
//			if (ifp->if_flags & IFF_RUNNING)
//				rtwn_stop(ifp);
		}
		break;
//	case SIOCS80211CHANNEL:
//		error = ieee80211_ioctl(ifp, cmd, data);
//		if (error == ENETRESET &&
//		    ic->ic_opmode == IEEE80211_M_MONITOR) {
//			if ((ifp->if_flags & (IFF_UP | IFF_RUNNING)) ==
//			    (IFF_UP | IFF_RUNNING))
//				rtwn_set_chan(sc, ic->ic_ibss_chan, NULL);
//			error = 0;
//		}
//		break;
	default:
		error = ieee80211_ioctl(ifp, cmd, data);
	}
	splx(s);
	usbd_ref_decr(sc->sc_udev);

	return (error);
}

int
urtwm_media_change(struct ifnet *ifp)
{
	int error;

	error = ieee80211_media_change(ifp);
	if (error != ENETRESET)
		return (error);

//	if ((ifp->if_flags & (IFF_UP | IFF_RUNNING)) ==
//	    (IFF_UP | IFF_RUNNING)) {
//		rtwn_stop(ifp);
//		error = rtwn_init(ifp);
//	}
	return (error);
}

void
urtwm_attach(struct device *parent, struct device *self, void *aux)
{
	struct urtwm_softc *sc = (struct urtwm_softc *)self;
	struct rtw88_softc *sc_sc = &sc->sc_sc;
	struct rtw_dev *rtwdev = &sc_sc->rtw_dev;
	struct usb_attach_arg *uaa = aux;
	struct ieee80211com *ic = &sc->sc_ic;
	struct ifnet *ifp = &ic->ic_if;
        struct rtw_efuse *efuse = &rtwdev->efuse;
	int ret;

	sc->sc_udev = uaa->device;
	sc->sc_iface = uaa->iface;

	rtwdev->chip = &rtw8822b_hw_spec;

	rtwdev->hci.type = RTW88_HCI_TYPE_USB;
	rtwdev->hci.ops = &rtw88_usb_ops;
	rtwdev->cookie = sc;

	usb_init_task(&sc->sc_task, urtwm_task, sc, USB_TASK_TYPE_GENERIC);

//	ret = rtw_usb_alloc_rx_bufs(rtwusb);
//	if (ret)
//		goto err_release_hw;
//
//	// TODO - ATTENTION - some flags are set here
	ret = rtw_core_init(rtwdev);
	if (ret) {
		return;
//		goto err_free_rx_bufs;
	}

	// TODO - setup usb before downloading firmware
	ret = rtw_usb_intf_init(rtwdev);
	if (ret) {
//		rtw_err(rtwdev, "failed to init USB interface\n");
		printf("%s: %s: failed to init USB interface, error=%i\n",
		    sc->sc_pdev.dv_xname, __func__, ret);
		return;
		// TODO: cleanup
//		goto err_deinit_core;
	}
//
//	ret = rtw_usb_init_tx(rtwdev);
//	if (ret) {
//		rtw_err(rtwdev, "failed to init USB TX\n");
//		goto err_destroy_usb;
//	}
//
//	ret = rtw_usb_init_rx(rtwdev);
//	if (ret) {
//		rtw_err(rtwdev, "failed to init USB RX\n");
//		goto err_destroy_txwq;
//	}

	ret = rtw88_chip_parameter_setup(rtwdev);
	if (ret) {
		printf("%s: %s: failed to setup chip parameters, error=%i\n",
		    sc->sc_pdev.dv_xname, __func__, ret);
		return;
	}

	ret = rtw88_chip_efuse_info_setup(rtwdev);
	if (ret) {
		printf("%s: %s: failed to setup chip efuse info, error=%i\n",
		    sc->sc_pdev.dv_xname, __func__, ret);
		return;
	}

	ret = rtw_chip_board_info_setup(rtwdev);
	if (ret) {
		printf("%s: failed to setup chip board info\n", __func__);
		return;
//		goto err_out;
	}

	ret = rtw_usb_switch_mode(rtwdev);
	if (ret) {
		/* Not a fail, but we do need to skip rtw_register_hw. */
		//                rtw_dbg(rtwdev, RTW_DBG_USB, "switching to USB 3 mode\n");
		printf("%s: switching to USB 3 mode\n", __func__);
		ret = 0;
		return;
		//                goto err_destroy_rxwq;
	}


	// ----- OpenBSD things -----
	ic->ic_phytype = IEEE80211_T_OFDM;	/* Not only, but not used. */
	ic->ic_opmode = IEEE80211_M_STA;	/* Default to BSS mode. */
	ic->ic_state = IEEE80211_S_INIT;

	/* Set device capabilities. */
	ic->ic_caps = 0;
//	    IEEE80211_C_MONITOR |	/* Monitor mode supported. */
//	    IEEE80211_C_SHPREAMBLE |	/* Short preamble supported. */
//	    IEEE80211_C_SHSLOT |	/* Short slot time supported. */
//	    IEEE80211_C_WEP |		/* WEP. */
//	    IEEE80211_C_RSN;		/* WPA/RSN. */

	IEEE80211_ADDR_COPY(ic->ic_myaddr, efuse->addr);

	ifp->if_softc = sc;
	ifp->if_flags = IFF_BROADCAST | IFF_SIMPLEX | IFF_MULTICAST;
	ifp->if_ioctl = urtwm_ioctl;
	ifp->if_start = urtwm_start;
//	ifp->if_watchdog = rtwn_watchdog;
	memcpy(ifp->if_xname, sc->sc_pdev.dv_xname, IFNAMSIZ);
	if_attach(ifp);
	ieee80211_ifattach(ifp);

	/* Override state transition machine. */
//	sc->sc_newstate = ic->ic_newstate;
	ic->ic_newstate = urtwm_newstate;
	ieee80211_media_init(ifp, urtwm_media_change, ieee80211_media_status);

	printf("%s: ----- OK -----\n", __func__);
	return;
}

